      const bi = (y, L, top, tipT, tipB2) => { ch(480 - 24, y, L, top ? R : B, true, top ? tipT : tipB2); ch(480 + 24, y, L, top ? B : R, true, top ? tipB2 : tipT); };
      if (st === 2) { cell(480, 270, 230, 190, 0); spindle(480, 270, 200, 160, 1); bi(220, 110, true, tipA[1], tipB[0]); bi(330, 70, !X, null, null); K.T(c, 'Equator', 480, 470, { s: 12 }); }
