    table: () => ({ cols: ['Feature', 'Mitosis', 'Meiosis'], rows: [['Divisions', 'One', 'Two'], ['Daughter cells', '2, diploid', '4, haploid'], ['Genetic make-up', 'Identical to parent', 'Different (crossing over, assortment)'], ['Pairing of homologues', 'No', 'Yes (synapsis)'], ['Where', 'Body cells: growth, repair', 'Gonads: gamete formation']] }),
