    init: () => ({ ca: 0, atp: true, L: 1, stim: false }),
    groups: s => [{ label: 'ATP', opts: [[true, 'Available'], [false, 'Exhausted (rigor)']].map(([k, l]) => ({ label: l, active: s.atp === k, on: () => { s.atp = k; } })) }],
    actions: s => [{ label: 'Nerve impulse (release Ca²⁺)', primary: true, on: () => { s.ca = 3; } }],
    tick: (s, dt) => { s.ca = Math.max(0, s.ca - dt); const target = s.ca > 0 && s.atp ? .62 : s.atp ? 1 : s.L; s.L += (target - s.L) * Math.min(1, dt * (s.ca > 0 ? 1.4 : .9)); return false; },
    msgOf: s => ({ t: !s.atp ? 'warn' : 'info', s: !s.atp ? 'No ATP: myosin heads stay attached to actin and cannot let go — the muscle stays stiff (rigor mortis).' : s.ca > 0 ? 'Ca²⁺ binds troponin, exposing sites on actin. Myosin heads attach, pivot (power stroke) and detach using ATP — actin slides inwards.' : 'Relaxed: Ca²⁺ is pumped back; binding sites are covered and filaments slide apart.' }),
